import sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'analysis/tools/python'))
from capstone import Cs,CS_ARCH_X86,CS_MODE_16
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();assert not out.exists() and out.is_relative_to(ROOT/'docs/recovery/evidence');image=(ROOT/'analysis/derived/td2ega-v1/TD2EGA.image.bin').read_bytes();sha=hashlib.sha256(image).hexdigest();assert sha=='8db38a02cc318a62b15928e217bb9f935699c6566088c21d32382a1c908a59c4';graph='analysis/flow/indirect-v8/direct-flow.json';g=json.loads((ROOT/graph).read_text());f=next(f for f in g['functions'] if f['entry']=='13A8:2E20');md=Cs(CS_ARCH_X86,CS_MODE_16);observations=[]
    for ip in sorted(f['instructions']):
        i=next(md.disasm(image[0x13a80+ip:0x13a80+ip+15],ip,count=1));observations.append({'site':f'13A8:{ip:04X}','bytes':i.bytes.hex(),'text':i.mnemonic+' '+i.op_str})
    for ip,raw in {0x2e23:'8b5606',0x2e26:'b441',0x2e28:'cd21',0x2e2a:'e9f7da',0x939:'e80e00',0x93f:'99',0x940:'8be5'}.items():assert image[0x13a80+ip:0x13a80+ip+len(raw)//2].hex()==raw
    deps=['docs/recovery/evidence/td2ega-table-scalar-build-v1.json','docs/recovery/evidence/td2ega-table-scalar-validation-v1.json','docs/recovery/evidence/td2ega-table-scalar-context-v1.json','docs/recovery/evidence/td2ega-sign-extension-context-v1.json']
    for path in deps:assert json.loads((ROOT/path).read_text())['result']=='pass'
    reference_path='docs/recovery/evidence/msdos-api-reference-v1.json';reference=json.loads((ROOT/reference_path).read_text());source=(ROOT/reference['private_path']).read_bytes();assert hashlib.sha256(source).hexdigest()==reference['sha256'];assert int(re.search(rb'^UNLINK +EQU (\d+)',source,re.MULTILINE).group(1))==65;callers=[{'owner':f['entry'],**c} for f in g['functions'] for c in f['calls'] if c['target']=='13A8:2E20'];record={'schema':1,'result':'pass','image_sha256':sha,'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'validator_dependencies':[{'path':p,'sha256':hashlib.sha256((ROOT/p).read_bytes()).hexdigest()} for p in deps],'instruction_observations':observations,'direct_caller_candidates':callers,'flow_ledger':graph,'flow_ledger_sha256':hashlib.sha256((ROOT/graph).read_bytes()).hexdigest(),'api_reference':{'path':reference_path,'sha256':hashlib.sha256((ROOT/reference_path).read_bytes()).hexdigest(),'source_path':reference['private_path'],'source_sha256':reference['sha256'],'url':reference['url'],'service_identifiers':{'UNLINK':65},'relevant_line_ranges':[[1420,1441],[1618,1618]]},'facts':['OneSSnearfilename/currentDS, PUSHBP/BP, DXargument thenAH41/INT21; branchvia shared0924 tail usesreturnedCF.','SuccessXORAX0/CF0, MOVSPreturnedBP/POPBP/plainfarRETF; returnedDX preserved.','FailureactualnearCALL094A pushes093C inSS, mapperrawreturnednearcoordinate admitted. Unexpectedchildreturn exposednotfollowed. Normalchildreturn thenAXFFFF/unprefixed99wordCWD ->DXFFFF, preservingmapperCF, MOVSPreturnedBP/POPBP/farRETF.','NativeadmittedSP>=20leaves16byte-minimum mapperchildentry afterouterBPsave/nearCALL; invalidsmallerprofile rejectedbeforeeffects. No change to frozen mapper.','ReturnedDS/BP/IFDF andservicebusmutations explicit. Nativebudget/adapterfailure and syntheticINTboundary areseparate fromoriginalDOSerrors andactualinterruptframes.'],'limits':'Staticoperands/historicalDOSidentity/frozenmapper/callerinventory only. NoactualDOS/fileoperation/device/IRQ/session/game/core/fidelity admission. Actualfilenamebounds/otherFLAGS/writers/lifetime/exclusion remainopen.'};out.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':'pass','sites':len(observations),'callers':len(callers),'DOS_identifiers':1}))
if __name__=='__main__':main()
